25.         internal static ResourceIdentifier GetSubscriptionResourceIdentifier(this ResourceIdentifier id)
26.         {
27.             if (id.ResourceType == SubscriptionResource.ResourceType)
28.                 return id;
29. 
30.             ResourceIdentifier parent = id.Parent;
31.             while (parent != null && parent.ResourceType != SubscriptionResource.ResourceType)
32.             {
33.                 parent = parent.Parent;
34.             }
35. 
36.             return parent?.ResourceType == SubscriptionResource.ResourceType ? parent : null;
37.         }
