40.         {
41.             var namePrefix = "Azure.ResourceManager.Assets.Profile.";
42.             var nameSuffix = profile switch
43.             {
44.                 AzureStackProfile.Profile20200901Hybrid => "2020-09-01-hybrid.json",
45.                 _ => throw new ArgumentOutOfRangeException(nameof(profile), profile, null)
46.             };
47.             return namePrefix + nameSuffix;
